      "card_ids": ["C45", "C46", "C47", "C48", "C49", "C50", "C51", "C52", "C53", "C54", "C55", "C56"]
    }
  ],
  "evidence_gaps": [
    "No direct experimental oral bioavailability data exist for the query molecule.",
    "No query-specific oral AUC/Cmax data are available; L3 records are for unrelated molecules (nobiletin, ACT-280778).",
    "The effect of the query's cyclic 1,3-dithiane 1,1,3,3-tetraoxide modification on verapamil-like scaffold F is unquantified.",
    "No query-specific data on absorption, first-pass metabolism, efflux, solubility, or formulation are available.",
